// Shared publications have their own draft/selection clocks; task drafts are untouched.
const pcScope=DTState.create(DTState.models.projectContextScope);
const pcDraft=new DTState.Draft(),pcRequests=new DTState.Revision(),pcPending=new DTState.Pending();
let pcState=null,pcChanges=new Map(),pcFile=null,pcCanPublish=false,pcLoaded=false,pcActiveFlow=null;
const pcCall=async(name,args)=>(await api('/api/tool/'+name,args)).result;
function pcMessage(value,error=false){$('pcMessage').textContent=value;$('pcMessage').className=error?'pc-message err-text':'pc-message hint';}
function pcDirty(){pcDraft.mark('publication');$('pcDirty').textContent='Unpublished edits';}
function pcLeave(){return !pcPending.value&&(!pcDraft.dirty||confirm('Discard unpublished project edits?'));}
async function pcBusy(fn){if(pcPending.value)return;pcPending.value++;const controls=[...$('pcPanel').querySelectorAll('button,input,textarea,select')].map(e=>[e,e.disabled]);controls.forEach(([e])=>e.disabled=true);try{await fn();}catch(e){pcMessage(e.message,true);}finally{pcPending.value--;controls.forEach(([e,disabled])=>e.disabled=disabled);pcPermissions();}}
function pcPermissions(){const current=!pcState?.revision||pcState.revision===pcState.currentRevision;$('pcFields').disabled=!pcCanPublish||!current;$('pcPublish').disabled=!pcCanPublish||!current;$('pcNew').disabled=!pcCanPublish;$('pcRestore').disabled=!pcCanPublish||current;$('pcId').readOnly=!!pcState?.revision;$('pcRevision').disabled=!pcState?.revision;$('pcDownload').disabled=!pcFile;$('pcDossier').disabled=!pcCanPublish||!current;$('pcReason').disabled=!pcCanPublish;}
function pcDocument(){return{...pcState.document,title:$('pcTitle').value,summary:$('pcSummary').value,body:$('pcBody').value,repositories:$('pcRepos').value.split(',').map(x=>x.trim()).filter(Boolean),tags:$('pcTags').value.split(',').map(x=>x.trim()).filter(Boolean),services:JSON.parse($('pcServices').value)};}
function pcFill(r){pcState=r;pcChanges.clear();pcFile=null;pcActiveFlow=null;pcDraft.clear();$('pcDirty').textContent='';$('pcId').value=r.id||'';for(const[field,id]of [['title','pcTitle'],['summary','pcSummary'],['body','pcBody']])$(id).value=r.document[field]||'';$('pcRepos').value=(r.document.repositories||[]).join(', ');$('pcTags').value=(r.document.tags||[]).join(', ');$('pcServices').value=JSON.stringify(r.document.services||[],null,2);$('pcReason').value='';$('pcDossier').value='';$('pcPath').value='';$('pcFileBody').value='';$('pcFileSummary').value='';$('pcRetainedGraph').hidden=true;$('pcFileEdits').hidden=true;$('pcFlowEdits').hidden=true;$('pcRevision').replaceChildren();for(const h of r.history||[]){const o=document.createElement('option');o.value=h.revision;o.textContent=h.at+' · '+h.revision.slice(0,10)+' · '+h.reason;$('pcRevision').append(o);}if(r.revision&&!r.history?.some(h=>h.revision===r.currentRevision)){const o=document.createElement('option');o.value=r.currentRevision;o.textContent='Current publication';$('pcRevision').prepend(o);}$('pcRevision').value=r.revision||'';$('pcRevision').disabled=!r.revision;$('pcPublished').textContent=r.revision?'Viewing '+(r.revision===r.currentRevision?'current':'historical')+' publication · '+r.revision:'New unpublished project context';pcRender();pcPermissions();}
function pcRender(){const r={...pcState,document:pcDocument()};DTProjectContext.render($('pcPreview'),r,{readFile:async path=>{const file=r.files.find(f=>f.path===path);return pcCall('project_context_get',{id:r.id,revision:r.revision,path,encoding:/^image\/(png|jpeg|webp)$/.test(file.mime)?'base64':'utf8',view:false});},onFile:f=>{pcFile=f;$('pcDownload').disabled=false;$('pcFileEdits').hidden=false;$('pcPath').value=f.path;$('pcFileSummary').value=f.summary;$('pcFileBody').value=f.encoding==='utf8'?f.content:'';$('pcFileBody').disabled=f.encoding!=='utf8'||!pcCanPublish||r.revision!==r.currentRevision;$('pcFileKind').textContent=f.encoding==='utf8'?'Edit text, then Stage file. Publication applies all staged changes together.':'Binary evidence. Download the retained file or upload a replacement.';},onService:(s,f)=>{pcActiveFlow=f?{service:s.service,id:f.id}:null;$('pcFlowEdits').hidden=!f;if(f){$('pcFlowSummary').value=f.summary;$('pcFlowBasis').value=f.basis;$('pcFlowAssumptions').value=f.assumptions.join('\n');$('pcFlowGaps').value=f.gaps.join('\n');}}});}
async function pcList(){const r=await pcCall('project_context_find',{query:$('pcSearch').value,limit:200});pcCanPublish=r.canPublish;const selected=pcState?.id;$('pcProjects').replaceChildren();const none=document.createElement('option');none.value='';none.textContent=r.total?'Choose a published project':'No published project context yet';$('pcProjects').append(none);for(const p of r.contexts){const o=document.createElement('option');o.value=p.id;o.textContent=p.title+' · '+p.services.length+' services';$('pcProjects').append(o);}$('pcProjects').value=selected||'';$('pcPolicy').textContent=r.canPublish?'Shared across users and chats. You can publish versioned changes. Private task contexts stay separate.':'Shared across users and chats. Read only; propose changes in your task context for an admin.';pcPermissions();}
async function pcLoad(id,revision){const ticket=pcRequests.advance(),draft=pcDraft.revision;const r=await pcCall('project_context_get',{id,revision,view:false});if(!pcRequests.current(ticket)||draft!==pcDraft.revision)return;pcCanPublish=r.canPublish;pcFill(r);$('pcProjects').value=r.id;pcMessage('Retained publication loaded. Compare source revisions before reuse.');}
async function pcSelect(mode){pcScope.to(mode);$('cxTaskMemory').hidden=mode==='project';$('pcPanel').hidden=mode!=='project';$('cxScopeTask').setAttribute('aria-pressed',String(mode!=='project'));$('cxScopeProject').setAttribute('aria-pressed',String(mode==='project'));if(mode==='project'){await pcList();const params=new URLSearchParams(location.hash.split('?')[1]||'');if(params.get('project')&&params.get('project')!==pcState?.id)await pcLoad(params.get('project'));}}
function pcInit(){if(pcLoaded)return;pcLoaded=true;
 $('cxScopeTask').onclick=()=>pcSelect('task').catch(e=>pcMessage(e.message,true));$('cxScopeProject').onclick=()=>pcBusy(()=>pcSelect('project'));
 $('pcSearchButton').onclick=()=>pcBusy(pcList);$('pcProjects').onchange=()=>{const id=$('pcProjects').value;if(id&&pcLeave())pcBusy(()=>pcLoad(id));};
 $('pcNew').onclick=()=>{if(!pcLeave())return;pcRequests.advance();pcFill({id:'',currentRevision:null,revision:null,files:[],history:[],canPublish:true,document:{title:'',summary:'',body:'',repositories:[],tags:[],services:[],architecture:[],status:'active'}});pcMessage('Give this project a stable id, explain what is known, and publish only shareable evidence.');$('pcId').focus();};
 $('pcRevision').onchange=()=>{if(pcLeave())pcBusy(()=>pcLoad(pcState.id,$('pcRevision').value));};
 $('pcFields').addEventListener('input',pcDirty);$('pcDossier').oninput=pcDirty;
 $('pcPreviewDraft').onclick=()=>{try{pcRender();pcMessage('Local draft preview. Publish to make it shared.');}catch(e){pcMessage('Services JSON: '+e.message,true);}};
 $('pcApplyFlow').onclick=()=>{if(!pcActiveFlow)return;try{const doc=pcDocument(),f=doc.services.find(s=>s.service===pcActiveFlow.service).flows.find(f=>f.id===pcActiveFlow.id);Object.assign(f,{summary:$('pcFlowSummary').value,basis:$('pcFlowBasis').value,assumptions:$('pcFlowAssumptions').value.split('\n').filter(Boolean),gaps:$('pcFlowGaps').value.split('\n').filter(Boolean)});$('pcServices').value=JSON.stringify(doc.services,null,2);pcDirty();pcRender();pcMessage('Flow edits staged in the local document. Evidence references remain editable in Service contracts JSON.');}catch(e){pcMessage(e.message,true);}};
 $('pcNewFile').onclick=()=>{pcFile=null;$('pcFileEdits').hidden=false;$('pcPath').value='';$('pcFileSummary').value='';$('pcFileBody').value='';$('pcFileBody').disabled=false;$('pcFileKind').textContent='A new text artifact; scripts and queries remain inert.';};
 $('pcStageFile').onclick=()=>{const file={path:$('pcPath').value,content:$('pcFileBody').value,summary:$('pcFileSummary').value};if(pcFile?.encoding==='base64')return pcMessage('Upload a replacement for binary evidence.',true);pcChanges.set(file.path,file);pcDirty();pcMessage(pcChanges.size+' file changes staged; publish to share.');};
 $('pcArchive').onclick=()=>{if(!pcFile)return;pcChanges.set(pcFile.path,{path:pcFile.path,archive:true});pcDirty();pcMessage('Archive staged; historical revisions retain the original file.');};
 $('pcUpload').onchange=()=>pcBusy(async()=>{const f=$('pcUpload').files[0];if(!f)return;if(f.size>2*1048576)throw Error('Choose a file up to 2 MiB; larger dossier imports use the retained result directly.');let binary='';const data=new Uint8Array(await f.arrayBuffer());for(let i=0;i<data.length;i+=8192)binary+=String.fromCharCode(...data.subarray(i,i+8192));pcChanges.set(f.name,{path:f.name,content:btoa(binary),encoding:'base64',summary:f.name});pcDirty();pcMessage('Upload staged. Review shareability before publishing.');$('pcUpload').value='';});
 $('pcDownload').onclick=()=>pcBusy(async()=>{if(!pcFile)throw Error('Select a retained file');const r=await pcCall('project_context_get',{id:pcState.id,revision:pcState.revision,path:pcFile.path,encoding:'base64',view:false});const a=document.createElement('a'),url=URL.createObjectURL(new Blob([Uint8Array.from(atob(r.file.content),c=>c.charCodeAt(0))]));a.href=url;a.download=pcFile.path.split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 const publish=restore=>pcBusy(async()=>{if(!pcState)throw Error('Open or create a project context');if(!$('pcReason').value.trim()){$('pcEditDetails').open=true;$('pcReason').focus();throw Error('Explain the publication reason first.');}const r=await pcCall('project_context_save',{id:$('pcId').value,expected_revision:pcState.currentRevision||null,reason:$('pcReason').value,...(restore?{restore_revision:pcState.revision}:{document:pcDocument(),files:[...pcChanges.values()],...($('pcDossier').value.trim()?{dossier:$('pcDossier').value.trim()}:{})})});pcFill(r);await pcList();pcMessage(restore?'Historical content restored as a new publication.':'Published. Previous revisions and their files remain readable.');});
 $('pcPublish').onclick=()=>publish(false);$('pcRestore').onclick=()=>publish(true);
 $('pcOpenGraph').onclick=()=>pcBusy(async()=>{if(!pcState?.revision)throw Error('Open a retained publication first');const wanted=pcActiveFlow?.service,path=pcState.files.find(f=>f.path==='services/'+wanted+'/dossier.json')?.path||pcState.files.find(f=>f.path.endsWith('/dossier.json'))?.path;if(!path)throw Error('This publication has no retained service dossier');const r=await pcCall('project_context_get',{id:pcState.id,revision:pcState.revision,path,diagram:true,...(pcActiveFlow?{flow:pcActiveFlow.id}:{}),view:false});$('pcRetainedGraph').href=r.diagramView;$('pcRetainedGraph').hidden=false;pcMessage('Retained graph prepared from this publication; no indexing or live queries were started.');});
 $('pcTemplate').onclick=()=>pcBusy(async()=>{const r=await pcCall('project_context_get',{});$('pcTemplateText').textContent=JSON.stringify(r.template,null,2);$('pcTemplateText').hidden=false;});
 window.addEventListener('beforeunload',e=>{if(pcDraft.dirty){e.preventDefault();e.returnValue='';}});
 const params=new URLSearchParams(location.hash.split('?')[1]||'');if(params.has('project'))pcBusy(()=>pcSelect('project'));
}
document.addEventListener('DOMContentLoaded',pcInit);
